"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[20930],{3378:e=>{e.exports=JSON.parse('{"id":"2026-09-24-outboundcontent-on-sms-delivery-receipts","date":"2026-09-24","products":["Connect","APIs"],"product":"Connect","channel":"SMS","changeType":"Added","title":"outboundContent on SMS delivery receipts","excerpt":"SMS delivery receipts now document the outboundContent object \u2014 a structured copy of the original outbound message the receipt refers to. It lets you reconcile a delivery receipt with the exact content that was sent without keeping your own copy of the outbound payload.","hasArticle":true,"bodyHtml":"<p>SMS delivery receipts now document the <code>outboundContent</code> object \u2014 a structured copy of the original outbound message the receipt refers to. It lets you reconcile a delivery receipt with the exact content that was sent without keeping your own copy of the outbound payload.</p>\\n<p>Key points:</p>\\n<ul>\\n<li><code>outboundContent</code> is attached only to the <code>queued</code> receipt sent when the message is accepted for processing. Other <code>queued</code> receipts \u2014 for example, for scheduled messages \u2014 do not include it, and it is omitted from every other status (<code>sent</code>, <code>delivered</code>, <code>undelivered</code>, etc.).</li>\\n<li>For SMS, <code>channel</code> is always <code>sms</code> and <code>contentType</code> is always <code>text</code>; the message text is carried in <code>body.text</code>.</li>\\n<li>When PII masking applies to the sub-account or destination country, <code>body</code> is omitted and a <code>meta</code> object describes the redaction (<code>redacted</code>, <code>redactionReason</code>) instead.</li>\\n<li>Requires delivery receipt format V7 or later. If your account is on an earlier format, contact support to activate the latest version.</li>\\n</ul>\\n<p>The guide includes sample receipts both with plain <code>outboundContent</code> and with masked content.</p>\\n<h2>Read more</h2>\\n<ul>\\n<li><a href=\\"/connect/docs/delivery-receipts-for-outbound-sms\\">Delivery receipts for outbound SMS</a></li>\\n</ul>\\n"}')}}]);